WITH flattened_attrs AS (SELECT id, customer_id, created_at, coupon_codes, items, TRANSFORM(items, item -> item.product_id) AS product_ids, COALESCE(attributes['utm_source'], 'direct') AS utm_source_or_default, attributes['gift'] AS gift FROM carts WHERE customer_id IS NOT NULL) SELECT DATE_TRUNC('DAY', created_at) AS activity_day, MAX(created_at) AS ended_at, COUNT(*) AS event_count, MIN(created_at) AS first_seen, (UNIX_TIMESTAMP(MAX(created_at)) - UNIX_TIMESTAMP(MIN(created_at))) / 60 AS span_minutes FROM flattened_attrs GROUP BY DATE_TRUNC('DAY', created_at) ORDER BY activity_day NULLS LAST;
